MATCH (s:PlantItem {tag: 'D-9701'}), (t:PlantItem {tag: 'V-10101'})
RETURN s.tag AS from_tag, t.tag AS to_tag,
       EXISTS {
         MATCH p = (s)-[:send_to*0..]->(t)
         WHERE all(n IN nodes(p) WHERE n.tag IS NULL OR n.tag <> 'E-10101')
       } AS can_flow_without_E_10101

